import base64, ctypes as c, io, os, shutil, subprocess, time
from pathlib import Path
from pywinauto import Desktop
from pywinauto.keyboard import send_keys
import psutil
from PIL import Image

ROOT=Path(r"C:\dev\flyExplorer")
EXE=ROOT/"out"/"winui"/"Release"/"flyExplorer.exe"
profile=Path(os.environ["USERPROFILE"])
targets=("바탕 화면","문서","다운로드","사진","음악","동영상")

def until(fn,why,timeout=25):
    end=time.monotonic()+timeout
    while time.monotonic()<end:
        try:
            v=fn()
            if v:return v
        except Exception:pass
        time.sleep(.25)
    raise AssertionError(why)

def find_auto(root,auto_id):
    for x in root.descendants():
        try:
            if x.element_info.automation_id==auto_id:return x
        except Exception:pass
    return None

def rows_for(root):
    found={}
    for item in root.descendants():
        try:
            if item.element_info.control_type!="ListItem":continue
            name=item.element_info.name or item.window_text()
            for t in targets:
                if t in name:found.setdefault(t,(item,name))
        except Exception:pass
    return found

def shot(window):
    img=window.capture_as_image().convert("RGB")
    buf=io.BytesIO();img.save(buf,format="JPEG",quality=86,optimize=True)
    return base64.b64encode(buf.getvalue()).decode("ascii")

owned=ROOT/"logs"/"known-folder-artwork-visual"
if owned.exists():shutil.rmtree(owned)
(owned/"localappdata"/"flyExplorer").mkdir(parents=True)
(owned/"localappdata"/"flyExplorer"/"ui-preferences-v1.txt").write_text(
 "schema=2\r\nlanguage=ko-KR\r\ntheme=dark\r\nview=large-icons\r\n",encoding="ascii",newline="")
env=os.environ.copy();env["LOCALAPPDATA"]=str(owned/"localappdata")
p=subprocess.Popen([str(EXE),str(profile)],cwd=EXE.parent,env=env)
fw=None
try:
    fw=until(lambda:next((x for x in Desktop(backend="uia").windows(process=p.pid)
                         if "flyExplorer" in x.window_text()),None),"flyExplorer window missing")
    try:fw.move_window(x=40,y=40,width=972,height=720,repaint=True)
    except Exception:pass
    left=until(lambda:find_auto(fw,"LeftFiles"),"LeftFiles missing")
    rows=until(lambda:(lambda x:x if len(x)>=6 else None)(rows_for(left)),"Known Folder rows missing",25)
    time.sleep(1)
    total=0
    for t in targets:
        item,name=rows[t]
        imgs=[x for x in item.descendants() if x.element_info.control_type=="Image"
              and x.element_info.name=="Windows Known Folder artwork"]
        total+=len(imgs)
        r=item.rectangle()
        print("FLY_VISUAL",t,r.left,r.top,r.width(),r.height(),"IMAGES",len(imgs),flush=True)
    print("FLY_KNOWN_ARTWORK_TOTAL",total,flush=True)
    if total!=6:raise AssertionError(f"expected six artwork images, got {total}")
    print("FLY_SCREENSHOT_BEGIN",flush=True);print(shot(fw),flush=True);print("FLY_SCREENSHOT_END",flush=True)
finally:
    if p.poll() is None:
        if fw:c.windll.user32.PostMessageW(fw.handle,0x10,0,0)
        try:p.wait(timeout=10)
        except subprocess.TimeoutExpired:p.terminate();p.wait(timeout=8)
print("FLY_PROCESS_EXIT",p.returncode,flush=True)

before=set()
for w in Desktop(backend="uia").windows(control_type="Window"):
    try:
        if psutil.Process(w.element_info.process_id).name().lower()=="explorer.exe":before.add(w.handle)
    except Exception:pass
subprocess.Popen(["explorer.exe","/separate,",str(profile)])
ew=None
try:
    def newexp():
        for w in Desktop(backend="uia").windows(control_type="Window"):
            try:
                if w.handle in before:continue
                if psutil.Process(w.element_info.process_id).name().lower()=="explorer.exe":return w
            except Exception:pass
        return None
    ew=until(newexp,"Explorer window missing",20)
    try:ew.move_window(x=40,y=40,width=972,height=720,repaint=True)
    except Exception:pass
    ew.set_focus();send_keys("^+2");time.sleep(1.5)
    erows=until(lambda:(lambda x:x if len(x)>=6 else None)(rows_for(ew)),"Explorer Known Folder rows missing",20)
    for t in targets:
        item,name=erows[t];r=item.rectangle()
        print("EXPLORER_VISUAL",t,r.left,r.top,r.width(),r.height(),flush=True)
    print("EXPLORER_SCREENSHOT_BEGIN",flush=True);print(shot(ew),flush=True);print("EXPLORER_SCREENSHOT_END",flush=True)
finally:
    if ew:
        try:ew.close()
        except Exception:pass

